<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>The Power of Vaccination: From Smallpox Eradication to COVID-19 in Record Time</title>

    <!-- Fonts: Swiss Modern - Archivo + Nunito -->
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700;800&family=Nunito:wght@400;500;600;700&display=swap" rel="stylesheet">

    <style>
        /* ===========================================
           CSS CUSTOM PROPERTIES (SWISS MODERN THEME)
           Clean, precise, Bauhaus-inspired
           =========================================== */
        :root {
            /* Colors */
            --bg-primary: #ffffff;
            --bg-secondary: #f8f9fa;
            --text-primary: #1a1a1a;
            --text-secondary: #555555;
            --accent: #ff3300;
            --accent-light: rgba(255, 51, 0, 0.1);
            --grid-line: rgba(0, 0, 0, 0.08);

            /* Typography */
            --font-display: 'Archivo', sans-serif;
            --font-body: 'Nunito', sans-serif;
            --title-size: clamp(1.75rem, 5vw, 3.5rem);
            --h2-size: clamp(1.25rem, 3.5vw, 2.25rem);
            --h3-size: clamp(1rem, 2.5vw, 1.5rem);
            --body-size: clamp(0.75rem, 1.5vw, 1.1rem);
            --small-size: clamp(0.65rem, 1.2vw, 0.9rem);
            --label-size: clamp(0.6rem, 1vw, 0.8rem);

            /* Spacing */
            --slide-padding: clamp(1.5rem, 4vw, 4rem);
            --content-gap: clamp(0.75rem, 2vw, 1.5rem);
            --element-gap: clamp(0.5rem, 1.5vw, 1rem);

            /* Animation */
            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.6s;
        }

        /* ===========================================
           BASE STYLES
           =========================================== */
        * { margin: 0; padding: 0; box-sizing: border-box; }

        /* ===========================================
           VIEWPORT FITTING: MANDATORY BASE STYLES
           =========================================== */
        html, body {
            height: 100%;
            overflow-x: hidden;
        }

        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }

        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
            background: var(--bg-primary);
        }

        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }

        /* ===========================================
           TYPOGRAPHY SYSTEM
           =========================================== */
        h1 {
            font-family: var(--font-display);
            font-size: var(--title-size);
            font-weight: 800;
            line-height: 1.1;
            color: var(--text-primary);
            letter-spacing: -0.02em;
        }

        h2 {
            font-family: var(--font-display);
            font-size: var(--h2-size);
            font-weight: 700;
            line-height: 1.2;
            color: var(--text-primary);
            margin-bottom: var(--content-gap);
        }

        h3 {
            font-family: var(--font-display);
            font-size: var(--h3-size);
            font-weight: 600;
            color: var(--text-primary);
        }

        p, li {
            font-family: var(--font-body);
            font-size: var(--body-size);
            line-height: 1.5;
            color: var(--text-secondary);
        }

        /* ===========================================
           ANIMATIONS
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(20px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }

        .slide.visible .reveal {
            opacity: 1;
            transform: translateY(0);
        }

        .reveal:nth-child(1) { transition-delay: 0.1s; }
        .reveal:nth-child(2) { transition-delay: 0.2s; }
        .reveal:nth-child(3) { transition-delay: 0.3s; }
        .reveal:nth-child(4) { transition-delay: 0.4s; }
        .reveal:nth-child(5) { transition-delay: 0.5s; }
        .reveal:nth-child(6) { transition-delay: 0.6s; }

        /* ===========================================
           NAVIGATION DOTS
           =========================================== */
        .nav-dots {
            position: fixed;
            right: clamp(0.75rem, 2vw, 1.5rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 8px;
            z-index: 100;
        }

        .nav-dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: var(--text-secondary);
            opacity: 0.3;
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .nav-dot.active {
            opacity: 1;
            background: var(--accent);
            transform: scale(1.3);
        }

        /* ===========================================
           SLIDE 1: TITLE SLIDE
           =========================================== */
        .title-slide {
            background: var(--bg-primary);
            position: relative;
        }

        .title-slide::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 6px;
            background: var(--accent);
        }

        .title-slide .slide-content {
            justify-content: flex-end;
            padding-bottom: clamp(3rem, 8vh, 6rem);
        }

        .title-slide h1 {
            max-width: 90%;
            margin-bottom: var(--content-gap);
        }

        .title-meta {
            display: flex;
            flex-wrap: wrap;
            gap: clamp(1rem, 3vw, 2rem);
            align-items: center;
            margin-top: var(--content-gap);
        }

        .title-meta span {
            font-family: var(--font-body);
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        .source-badge {
            display: inline-flex;
            align-items: center;
            gap: 6px;
            background: var(--bg-secondary);
            padding: 6px 12px;
            border-radius: 4px;
            font-size: var(--label-size);
            font-weight: 600;
            color: var(--text-primary);
        }

        .source-badge svg {
            width: 14px;
            height: 14px;
        }

        /* ===========================================
           SLIDE 2: VACCINE TIMELINE ACCELERATION
           =========================================== */
        .timeline-chart {
            display: flex;
            flex-direction: column;
            gap: clamp(0.4rem, 1.2vh, 0.8rem);
            margin-top: var(--content-gap);
        }

        .timeline-row {
            display: grid;
            grid-template-columns: 120px 1fr 80px;
            align-items: center;
            gap: clamp(0.5rem, 2vw, 1.5rem);
        }

        .timeline-disease {
            font-family: var(--font-display);
            font-size: var(--small-size);
            font-weight: 600;
            color: var(--text-primary);
            text-align: right;
        }

        .timeline-bar-container {
            height: clamp(20px, 3vh, 32px);
            background: var(--bg-secondary);
            position: relative;
            border-left: 2px solid var(--text-primary);
        }

        .timeline-bar {
            height: 100%;
            background: var(--accent);
            opacity: 0.7;
            transition: width 1s var(--ease-out-expo);
        }

        .timeline-bar.covid {
            background: var(--accent);
            opacity: 1;
            box-shadow: 0 0 20px rgba(255, 51, 0, 0.4);
        }

        .timeline-bar.measles {
            background: #22c55e;
            opacity: 0.7;
        }

        .timeline-bar.hepb {
            background: #3b82f6;
            opacity: 0.7;
        }

        .timeline-years {
            font-family: var(--font-display);
            font-size: var(--small-size);
            font-weight: 700;
            color: var(--text-primary);
            white-space: nowrap;
        }

        .timeline-years .highlight {
            color: var(--accent);
        }

        .chart-legend {
            display: flex;
            gap: clamp(1rem, 3vw, 2rem);
            margin-top: var(--element-gap);
            padding-top: var(--element-gap);
            border-top: 1px solid var(--grid-line);
        }

        .legend-item {
            display: flex;
            align-items: center;
            gap: 8px;
            font-size: var(--label-size);
            color: var(--text-secondary);
        }

        .legend-color {
            width: 16px;
            height: 8px;
            border-radius: 2px;
        }

        .legend-color.accent { background: var(--accent); }
        .legend-color.green { background: #22c55e; }
        .legend-color.blue { background: #3b82f6; }

        /* ===========================================
           SLIDE 3: US DISEASE ELIMINATION TABLE
           =========================================== */
        .data-table {
            width: 100%;
            border-collapse: collapse;
            margin-top: var(--content-gap);
            font-size: var(--small-size);
        }

        .data-table th {
            font-family: var(--font-display);
            font-weight: 700;
            font-size: var(--label-size);
            text-transform: uppercase;
            letter-spacing: 0.05em;
            color: var(--text-secondary);
            text-align: left;
            padding: clamp(0.4rem, 1vh, 0.75rem) clamp(0.5rem, 1.5vw, 1rem);
            border-bottom: 2px solid var(--text-primary);
        }

        .data-table th:not(:first-child) {
            text-align: right;
        }

        .data-table td {
            font-family: var(--font-body);
            padding: clamp(0.4rem, 1vh, 0.75rem) clamp(0.5rem, 1.5vw, 1rem);
            border-bottom: 1px solid var(--grid-line);
            color: var(--text-primary);
        }

        .data-table td:not(:first-child) {
            text-align: right;
            font-family: var(--font-display);
            font-weight: 600;
        }

        .data-table tr.eliminated td {
            background: rgba(34, 197, 94, 0.08);
        }

        .data-table tr.eliminated td:first-child {
            border-left: 3px solid #22c55e;
        }

        .data-table tr.partial td:first-child {
            border-left: 3px solid var(--accent);
        }

        .reduction-badge {
            display: inline-block;
            padding: 2px 8px;
            border-radius: 3px;
            font-size: var(--label-size);
            font-weight: 700;
        }

        .reduction-badge.green {
            background: #22c55e;
            color: white;
        }

        .reduction-badge.orange {
            background: var(--accent);
            color: white;
        }

        .reduction-badge.yellow {
            background: #f59e0b;
            color: white;
        }

        /* ===========================================
           SLIDE 4: MEASLES HEATMAP
           =========================================== */
        .heatmap-container {
            display: grid;
            grid-template-columns: 80px 1fr;
            grid-template-rows: auto 1fr auto;
            gap: var(--element-gap);
            margin-top: var(--content-gap);
        }

        .heatmap-title {
            grid-column: 1 / -1;
            font-family: var(--font-display);
            font-size: var(--h3-size);
            font-weight: 600;
            color: var(--text-primary);
        }

        .heatmap-y-axis {
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            font-size: var(--label-size);
            color: var(--text-secondary);
            text-align: right;
            padding-right: 8px;
        }

        .heatmap-grid {
            display: grid;
            grid-template-rows: repeat(5, 1fr);
            gap: 2px;
            height: clamp(150px, 25vh, 250px);
        }

        .heatmap-row {
            display: grid;
            grid-template-columns: repeat(12, 1fr);
            gap: 2px;
        }

        .heatmap-cell {
            border-radius: 2px;
            transition: transform 0.2s ease;
        }

        .heatmap-legend {
            grid-column: 1 / -1;
            display: flex;
            align-items: center;
            gap: var(--element-gap);
            font-size: var(--label-size);
            color: var(--text-secondary);
        }

        .heatmap-scale {
            display: flex;
            gap: 2px;
        }

        .heatmap-scale span {
            width: clamp(20px, 3vw, 40px);
            height: 12px;
            border-radius: 2px;
        }

        .milestone-annotations {
            display: flex;
            gap: clamp(1rem, 3vw, 3rem);
            margin-top: var(--content-gap);
            padding-top: var(--element-gap);
            border-top: 1px solid var(--grid-line);
        }

        .milestone {
            display: flex;
            flex-direction: column;
            gap: 4px;
        }

        .milestone-year {
            font-family: var(--font-display);
            font-size: var(--h3-size);
            font-weight: 800;
            color: var(--accent);
        }

        .milestone-desc {
            font-size: var(--label-size);
            color: var(--text-secondary);
            max-width: 150px;
        }

        /* ===========================================
           SLIDE 5: SMALLPOX ERADICATION
           =========================================== */
        .eradication-timeline {
            display: flex;
            flex-direction: column;
            gap: 0;
            margin-top: var(--content-gap);
            position: relative;
            padding-left: 30px;
        }

        .eradication-timeline::before {
            content: '';
            position: absolute;
            left: 8px;
            top: 0;
            bottom: 0;
            width: 2px;
            background: linear-gradient(to bottom, var(--accent), var(--text-secondary));
        }

        .timeline-event {
            position: relative;
            padding-left: clamp(1rem, 3vw, 2rem);
            padding-bottom: var(--content-gap);
        }

        .timeline-event::before {
            content: '';
            position: absolute;
            left: calc(-30px + 4px);
            top: 6px;
            width: 10px;
            height: 10px;
            border-radius: 50%;
            background: var(--accent);
            border: 2px solid var(--bg-primary);
        }

        .timeline-event:last-child::before {
            background: #22c55e;
        }

        .event-year {
            font-family: var(--font-display);
            font-size: var(--body-size);
            font-weight: 700;
            color: var(--accent);
            margin-bottom: 4px;
        }

        .event-title {
            font-family: var(--font-display);
            font-size: var(--body-size);
            font-weight: 600;
            color: var(--text-primary);
            margin-bottom: 4px;
        }

        .event-desc {
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        .eradication-facts {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: var(--element-gap);
            margin-top: var(--content-gap);
            padding-top: var(--element-gap);
            border-top: 1px solid var(--grid-line);
        }

        .fact-card {
            background: var(--bg-secondary);
            padding: var(--element-gap);
            border-radius: 4px;
            border-left: 3px solid var(--accent);
        }

        .fact-label {
            font-size: var(--label-size);
            color: var(--text-secondary);
            text-transform: uppercase;
            letter-spacing: 0.05em;
            margin-bottom: 4px;
        }

        .fact-value {
            font-family: var(--font-display);
            font-size: var(--h3-size);
            font-weight: 700;
            color: var(--text-primary);
        }

        /* ===========================================
           SLIDE 6: HERD IMMUNITY
           =========================================== */
        .herd-diagram {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: clamp(2rem, 5vw, 4rem);
            margin-top: var(--content-gap);
        }

        .diagram-circles {
            position: relative;
            width: clamp(200px, 40vw, 350px);
            height: clamp(200px, 40vw, 350px);
        }

        .diagram-circle {
            position: absolute;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .diagram-circle.outer {
            width: 100%;
            height: 100%;
            background: var(--bg-secondary);
            border: 3px solid var(--text-primary);
            top: 0;
            left: 0;
        }

        .diagram-circle.middle {
            width: 65%;
            height: 65%;
            background: rgba(255, 51, 0, 0.1);
            border: 2px solid var(--accent);
            top: 17.5%;
            left: 17.5%;
        }

        .diagram-circle.inner {
            width: 30%;
            height: 30%;
            background: var(--accent);
            top: 35%;
            left: 35%;
        }

        .diagram-label {
            position: absolute;
            font-size: var(--label-size);
            font-weight: 600;
            color: var(--text-secondary);
        }

        .diagram-label.top { top: -8%; left: 50%; transform: translateX(-50%); }
        .diagram-label.middle { top: 50%; right: -25%; transform: translateY(-50%); }
        .diagram-label.center { color: white; font-weight: 700; }

        .herd-explanation {
            max-width: 40%;
        }

        .herd-explanation h3 {
            margin-bottom: var(--element-gap);
        }

        .herd-list {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: var(--element-gap);
        }

        .herd-list li {
            display: flex;
            align-items: flex-start;
            gap: 10px;
        }

        .herd-list li::before {
            content: '';
            width: 8px;
            height: 8px;
            background: var(--accent);
            border-radius: 50%;
            margin-top: 6px;
            flex-shrink: 0;
        }

        /* ===========================================
           SLIDE 7: REMAINING CHALLENGES
           =========================================== */
        .challenges-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: var(--element-gap);
            margin-top: var(--content-gap);
        }

        .challenge-card {
            background: var(--bg-secondary);
            padding: var(--element-gap);
            border-radius: 4px;
            display: flex;
            flex-direction: column;
            gap: var(--element-gap);
        }

        .challenge-card.highlight {
            border: 2px solid var(--accent);
        }

        .challenge-disease {
            font-family: var(--font-display);
            font-size: var(--h3-size);
            font-weight: 700;
            color: var(--text-primary);
        }

        .challenge-stats {
            display: flex;
            gap: var(--content-gap);
        }

        .stat {
            display: flex;
            flex-direction: column;
        }

        .stat-value {
            font-family: var(--font-display);
            font-size: var(--h2-size);
            font-weight: 800;
            color: var(--accent);
        }

        .stat-label {
            font-size: var(--label-size);
            color: var(--text-secondary);
        }

        .challenge-bar {
            height: 8px;
            background: var(--bg-primary);
            border-radius: 4px;
            overflow: hidden;
        }

        .challenge-bar-fill {
            height: 100%;
            background: var(--accent);
            border-radius: 4px;
        }

        .challenge-bar-fill.partial {
            background: #f59e0b;
        }

        .challenge-note {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: auto;
        }

        .barriers-section {
            margin-top: var(--content-gap);
            padding-top: var(--element-gap);
            border-top: 1px solid var(--grid-line);
        }

        .barriers-title {
            font-family: var(--font-display);
            font-size: var(--body-size);
            font-weight: 700;
            color: var(--text-primary);
            margin-bottom: var(--element-gap);
        }

        .barriers-list {
            display: flex;
            flex-wrap: wrap;
            gap: var(--element-gap);
        }

        .barrier-tag {
            background: var(--bg-secondary);
            padding: 6px 12px;
            border-radius: 4px;
            font-size: var(--label-size);
            font-weight: 600;
            color: var(--text-primary);
            border: 1px solid var(--grid-line);
        }

        /* ===========================================
           SLIDE 8: TAKEAWAYS
           =========================================== */
        .takeaways-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: var(--element-gap);
            margin-top: var(--content-gap);
        }

        .takeaway-card {
            background: var(--bg-secondary);
            padding: var(--element-gap);
            border-radius: 4px;
            display: flex;
            gap: var(--element-gap);
            align-items: flex-start;
        }

        .takeaway-card.full {
            grid-column: 1 / -1;
            background: linear-gradient(135deg, var(--accent) 0%, #cc2900 100%);
            color: white;
        }

        .takeaway-card.full h3,
        .takeaway-card.full p {
            color: white;
        }

        .takeaway-card.full .takeaway-number {
            background: white;
            color: var(--accent);
        }

        .takeaway-number {
            width: clamp(28px, 4vw, 40px);
            height: clamp(28px, 4vw, 40px);
            background: var(--accent);
            color: white;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-family: var(--font-display);
            font-weight: 800;
            font-size: var(--body-size);
            flex-shrink: 0;
        }

        .takeaway-text h3 {
            font-size: var(--body-size);
            margin-bottom: 4px;
        }

        .takeaway-text p {
            font-size: var(--small-size);
        }

        .call-to-action {
            margin-top: var(--content-gap);
            padding: var(--element-gap);
            border: 2px solid var(--text-primary);
            border-radius: 4px;
            text-align: center;
        }

        .call-to-action h3 {
            font-family: var(--font-display);
            font-size: var(--h3-size);
            font-weight: 700;
            margin-bottom: var(--element-gap);
        }

        .call-to-action p {
            max-width: 70%;
            margin: 0 auto;
        }

        /* ===========================================
           RESPONSIVE
           =========================================== */
        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap: clamp(0.4rem, 1.5vw, 1rem);
                --title-size: clamp(1.25rem, 4.5vw, 2.5rem);
                --h2-size: clamp(1rem, 3vw, 1.75rem);
            }
        }

        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
                --content-gap: clamp(0.3rem, 1vw, 0.75rem);
                --title-size: clamp(1.1rem, 4vw, 2rem);
                --body-size: clamp(0.7rem, 1.2vw, 0.95rem);
            }

            .nav-dots, .keyboard-hint, .decorative {
                display: none;
            }
        }

        @media (max-width: 600px) {
            .timeline-row {
                grid-template-columns: 80px 1fr 60px;
            }

            .herd-diagram {
                flex-direction: column;
            }

            .herd-explanation {
                max-width: 100%;
            }

            .challenges-grid,
            .takeaways-grid {
                grid-template-columns: 1fr;
            }

            .eradication-facts {
                grid-template-columns: 1fr;
            }

            .data-table {
                font-size: clamp(0.6rem, 2vw, 0.8rem);
            }
        }

        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }

            html {
                scroll-behavior: auto;
            }
        }
    </style>
